def ask_int(prompt, min_val=1):
    """Prompt until the user enters an integer >= min_val."""
    while True:
        try:
            val = int(input(prompt))
            if val >= min_val:
                return val
            print(f"Please enter an integer >= {min_val}.")
        except ValueError:
            print("That doesn't look like an integer – try again.")

